"""Авторские задачи базового курса 10 класса; ФРП, стр. 15–16, 32–33, 57."""
from author_tools import N,H,G,P
from math import sqrt
from fractions import Fraction
import ast

def _rows10a(key,data):
    out=[]
    for i,line in enumerate(data.strip().splitlines(),1):
        d,p,a,s,o=line.split('~');a=a.replace('−','-')
        if a.startswith('['):
            v=ast.literal_eval(a);answer=(v,'−2/3; 1') if key=='b10-205' and i==3 else v
        elif a.startswith('√'):answer=(sqrt(float(Fraction(a[1:].strip("()")))),{"√(1/3)":"√3/3","√(2/3)":"√6/3"}.get(a,a))
        elif '/' in a:answer=(float(Fraction(a)),a)
        else:answer=float(a)
        out.append((key+'-'+str(i),p,answer,s,o,d))
    return out

def B(n,title,data,subject=H,ref='15–16'):
    N(bank,10,n,subject,title,ref,_rows10a('b10-'+str(n),data),level='basic')

